/**
 * Writes DEVELOPMENT_TEAM into the generated Xcode project.
 *
 * WHY THIS EXISTS
 * ios/ is gitignored and regenerated by `expo prebuild`, so the team id you set
 * by hand in Xcode's Signing tab is wiped every time. That would be a minor
 * annoyance except that switching between the production and development
 * variants CHANGES THE BUNDLE ID, which forces a prebuild — so the team would
 * be lost on every switch, and every switch would fail with
 * "No code signing certificates are available" until you went back into Xcode.
 *
 * Reading it from the environment rather than hard-coding keeps a personal
 * Apple team id out of the repository. EAS builds ignore all of this — they
 * manage credentials server-side — so this only affects local device builds.
 *
 * Set APPLE_TEAM_ID in apps/mobile/.env (and .env.dev); with-env.sh exports it.
 * Unset, the plugin does nothing and Xcode behaves as it did before.
 */
const { withXcodeProject } = require('@expo/config-plugins')

module.exports = function withDevelopmentTeam(config) {
  return withXcodeProject(config, (cfg) => {
    const teamId = process.env.APPLE_TEAM_ID
    if (!teamId) return cfg

    const project = cfg.modResults
    const configurations = project.pbxXCBuildConfigurationSection()

    for (const key of Object.keys(configurations)) {
      const buildSettings = configurations[key].buildSettings
      // Comment entries in the pbxproj have no buildSettings; skip them.
      if (!buildSettings || buildSettings.PRODUCT_NAME === undefined) continue
      buildSettings.DEVELOPMENT_TEAM = `"${teamId}"`
      buildSettings.CODE_SIGN_STYLE = 'Automatic'
    }

    return cfg
  })
}
